import { createContext, useContext, useId, useRef, useState, type ComponentProps, type MouseEvent, type ReactNode } from 'react'
import { Dialog } from '@base-ui/react/dialog'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { Button } from '../../buttons/Button'
import styles from './AppShell.module.css'

/** Whether the shell has a navigation drawer for narrow screens, and how to open it. */
const DrawerContext = createContext<{ hasDrawer: boolean; isOpen: boolean; open: () => void; label: string }>({
  hasDrawer: false,
  isOpen: false,
  open: () => {},
  label: 'Navigation',
})

/** `null`, `false` and `undefined` render nothing, so they are no navigation either. */
const given = (node: ReactNode) => node != null && node !== false

export interface AppShellProps extends ComponentProps<'div'> {
  /** A Sidebar. Beside the content from 64rem; in the drawer below that. */
  sidebar?: ReactNode
  /** An AppHeader, above the content. */
  header?: ReactNode
  /**
   * What the drawer holds on narrow screens. Defaults to `sidebar`; pass it
   * for a top-navigation shell, whose links move into the drawer below 48rem.
   */
  mobileNavigation?: ReactNode
  /** Names the drawer and its button. */
  navigationLabel?: string
  /** The `id` of the `main` element, which the skip link targets. Generated if not given. */
  mainId?: string
  children: ReactNode
}

/**
 * The frame of an application: navigation, a header, and the page. The
 * sidebar stays put while the content scrolls; on narrow screens the
 * navigation moves into a drawer that the header's menu button opens.
 */
export function AppShell({
  sidebar,
  header,
  mobileNavigation,
  navigationLabel = 'Navigation',
  mainId,
  children,
  className,
  ...props
}: AppShellProps) {
  const [open, setOpen] = useState(false)
  const autoId = useId()
  const mainRef = useRef<HTMLElement>(null)
  const id = mainId ?? `${autoId}main`
  const hasSidebar = given(sidebar)
  const hasMobileNavigation = given(mobileNavigation)
  const drawerContent = hasMobileNavigation ? mobileNavigation : hasSidebar ? sidebar : null
  const hasDrawer = drawerContent !== null
  // A link chosen in the drawer navigates; the drawer should not stay over the new page.
  const closeOnLink = (e: MouseEvent) => {
    if ((e.target as HTMLElement).closest('a[href]')) setOpen(false)
  }
  return (
    <DrawerContext.Provider value={{ hasDrawer, isOpen: open, open: () => setOpen(true), label: navigationLabel }}>
      <div className={cn(styles.shell, hasSidebar && styles.withSidebar, hasMobileNavigation && styles.withMobileNavigation, className)} {...props}>
        {/* Focus is moved by hand: the browser's own jump would also scroll
            the window, and a generated id is not a tidy URL fragment. */}
        <a
          href={`#${id}`}
          className={styles.skip}
          onClick={(e) => {
            e.preventDefault()
            mainRef.current?.focus()
          }}
        >
          Skip to content
        </a>
        {/* The shell is the size container and the frame its grid, so the
            layout follows the shell's own width: an element cannot query itself. */}
        <div className={styles.frame}>
          {hasSidebar && <div className={styles.sidebar}>{sidebar}</div>}
          <div className={styles.column}>
            {header}
            <main ref={mainRef} id={id} tabIndex={-1} className={styles.main}>
              {children}
            </main>
          </div>
        </div>
      </div>
      {hasDrawer && (
        <Dialog.Root open={open} onOpenChange={setOpen}>
          <Dialog.Portal>
            <Dialog.Backdrop className={styles.backdrop} />
            <Dialog.Popup className={styles.drawer} onClick={closeOnLink}>
              <Dialog.Title className={styles.srOnly}>{navigationLabel}</Dialog.Title>
              <Dialog.Close className={styles.drawerClose} aria-label={`Close ${navigationLabel.toLowerCase()}`}>
                <Icon name="close" />
              </Dialog.Close>
              {drawerContent}
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
      )}
    </DrawerContext.Provider>
  )
}

export interface AppHeaderProps extends ComponentProps<'header'> {
  /** Breadcrumbs, or a logo and AppNav. */
  start?: ReactNode
  /** Search, notifications, the account menu. */
  end?: ReactNode
  children?: ReactNode
}

/** The bar above the content. Inside an AppShell with navigation it adds the drawer's menu button on narrow screens. */
export function AppHeader({ start, end, children, className, ...props }: AppHeaderProps) {
  const drawer = useContext(DrawerContext)
  return (
    <header className={cn(styles.header, className)} {...props}>
      {drawer.hasDrawer && (
        <Button
          variant="secondary"
          appearance="ghost"
          isIconOnly
          aria-label={`Open ${drawer.label.toLowerCase()}`}
          aria-haspopup="dialog"
          aria-expanded={drawer.isOpen}
          className={styles.menuButton}
          onClick={drawer.open}
        >
          <Icon name="menu" />
        </Button>
      )}
      {start && <div className={styles.start}>{start}</div>}
      {children && <div className={styles.center}>{children}</div>}
      {end && <div className={styles.end}>{end}</div>}
    </header>
  )
}

export interface AppNavItem {
  label: string
  href: string
}

export interface AppNavProps extends Omit<ComponentProps<'nav'>, 'children'> {
  items: AppNavItem[]
  /** The href of the page you are on. */
  currentHref?: string
  'aria-label'?: string
}

/** Top navigation links for a header. Hidden below 48rem, where the drawer holds them. */
export function AppNav({ items, currentHref, className, 'aria-label': ariaLabel = 'Main', ...props }: AppNavProps) {
  return (
    <nav aria-label={ariaLabel} className={cn(styles.nav, className)} {...props}>
      <ul>
        {items.map((item) => (
          <li key={item.href}>
            <a href={item.href} className={styles.navLink} aria-current={item.href === currentHref ? 'page' : undefined}>
              {item.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  )
}

/* The shell fills the viewport by default; set block-size on it to put it
   in a smaller box, as the stories do. The content column scrolls, so the
   sidebar and the header stay where they are. Breakpoints are the shell's
   own width (a container), which in an app is the viewport's. */
.shell {
  position: relative;
  container-type: inline-size;
  block-size: 100dvh;
  overflow: hidden;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
}

.frame {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  block-size: 100%;
}

.sidebar {
  display: none;
  min-block-size: 0;
  border-inline-end: 1px solid var(--border);
}

/* The sidebar from 64rem; below that it lives in the drawer. */
@container (min-width: 64rem) {
  .withSidebar .frame {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .withSidebar .sidebar {
    display: block;
  }
}

.column {
  display: flex;
  flex-direction: column;
  min-inline-size: 0;
  min-block-size: 0;
  overflow: auto;
}

.main {
  flex: 1;
  padding: var(--space-6);
  outline: none;
}
@container (min-width: 64rem) {
  .main {
    padding: var(--space-8);
  }
}

/* ---------------------------------------------------------------- skip
   Off screen until focused: the first Tab on the page, straight past the
   navigation to the content. */
.skip {
  position: absolute;
  inset-block-start: var(--space-2);
  inset-inline-start: var(--space-2);
  z-index: 60;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-field);
  background: var(--primary);
  color: var(--primary-foreground);
  font-size: var(--text-body);
  font-weight: 500;
  text-decoration: none;
  translate: 0 calc(-100% - var(--space-4));
}
.skip:focus-visible {
  translate: 0;
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* -------------------------------------------------------------- header */
.header {
  position: sticky;
  inset-block-start: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: var(--space-4);
  min-block-size: calc(var(--space-8) * 2);
  padding-inline: var(--space-4);
  border-block-end: 1px solid var(--border);
  background: var(--background);
}
@container (min-width: 64rem) {
  .header {
    padding-inline: var(--space-8);
  }
}

.start {
  display: flex;
  align-items: center;
  gap: var(--space-8);
  min-inline-size: 0;
}
.center {
  flex: 1;
  min-inline-size: 0;
}
.end {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-inline-start: auto;
}

/* The menu button only where the drawer is the navigation. */
@container (min-width: 64rem) {
  .withSidebar .menuButton {
    display: none;
  }
}
@container (min-width: 48rem) {
  .withMobileNavigation:not(.withSidebar) .menuButton {
    display: none;
  }
}

/* ----------------------------------------------------------------- nav */
.nav ul {
  display: flex;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
@container (max-width: 47.99rem) {
  .nav {
    display: none;
  }
}

.navLink {
  display: inline-flex;
  align-items: center;
  min-block-size: calc(var(--space-8) + var(--space-1));
  padding-inline: var(--space-3);
  border-radius: var(--radius-field);
  color: var(--muted-foreground);
  font-size: var(--text-body);
  font-weight: 500;
  text-decoration: none;
}
.navLink:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.navLink:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
/* The current page: foreground text on the subtle surface, not colour alone. */
.navLink[aria-current='page'] {
  background: var(--accent);
  color: var(--foreground);
}

/* -------------------------------------------------------------- drawer */
.backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: oklch(0% 0 0 / 50%);
  transition: opacity 150ms;
}
.backdrop[data-starting-style],
.backdrop[data-ending-style] {
  opacity: 0;
}

.drawer {
  position: fixed;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  inline-size: min(20rem, 85vw);
  background: var(--background);
  color: var(--foreground);
  box-shadow: var(--shadow-lg);
  outline: none;
  transition: translate 200ms;
}
/* The navigation inside (a Sidebar) takes the drawer's width, not its own. */
.drawer > :not(.drawerClose) {
  flex: 1;
  min-block-size: 0;
  inline-size: 100%;
}
.drawer[data-starting-style],
.drawer[data-ending-style] {
  translate: -100% 0;
}
/* [dir] rather than :dir(), which the build lowers to a :lang() list. */
:global([dir='rtl']) .drawer[data-starting-style],
:global([dir='rtl']) .drawer[data-ending-style] {
  translate: 100% 0;
}

.drawerClose {
  position: absolute;
  inset-block-start: var(--space-3);
  inset-inline-end: var(--space-3);
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-8);
  block-size: var(--space-8);
  padding: 0;
  border: 0;
  border-radius: var(--radius-field);
  background: transparent;
  color: var(--muted-foreground);
  font-size: var(--space-4);
  cursor: var(--cursor-button);
}
.drawerClose:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}
.drawerClose:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .backdrop,
  .drawer {
    transition: none;
  }
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
